pub fn adaptive_sort<T: Ord + Clone>(arr: &mut [T]) {
    let n = arr.len();
    if n <= 1 { return; }
    if n <= 32 { insertion_sort(arr); return; }
    // Find natural runs and merge them
    let mut runs: Vec<(usize, usize)> = Vec::new();
    let mut i = 0;
    while i < n - 1 {
        let start = i;
        if arr[i] > arr[i + 1] {
            while i < n - 1 && arr[i] > arr[i + 1] { i += 1; }
            arr[start..=i].reverse();
        } else {
            while i < n - 1 && arr[i] <= arr[i + 1] { i += 1; }
        }
        let end = i;
        if end - start < 31 {
            let e = std::cmp::min(start + 31, n - 1);
            insertion_sort(&mut arr[start..=e]);
            runs.push((start, e));
            i = e + 1;
        } else {
            runs.push((start, end));
            i = end + 1;
        }
    }
    if i == n - 1 { runs.push((i, i)); }
    // Merge runs bottom-up
    let mut buf = arr.to_vec();
