        runs = merged;
    }
}

fn insertion_sort<T: Ord>(a: &mut [T]) {
    for i in 1..a.len() {
        let mut j = i;
        while j > 0 && a[j - 1] > a[j] { a.swap(j, j - 1); j -= 1; }
    }
}

fn merge<T: Ord + Clone>(arr: &mut [T], buf: &mut [T], lo: usize, mid: usize, hi: usize) {
    buf[lo..=hi].clone_from_slice(&arr[lo..=hi]);
    let (mut i, mut j, mut k) = (lo, mid + 1, lo);
    while i <= mid && j <= hi {
        if buf[i] <= buf[j] { arr[k] = buf[i].clone(); i += 1; }
        else { arr[k] = buf[j].clone(); j += 1; }
        k += 1;
    }
    while i <= mid { arr[k] = buf[i].clone(); i += 1; k += 1; }
    while j <= hi { arr[k] = buf[j].clone(); j += 1; k += 1; }
